// Offline cache for the self-hosted __APP__ web build.
// Generated by scripts/build_site.py for upstream release __TAG__.
//
// Two caches per app:
//  - "static": files whose names carry a content hash (they never change under the same
//    name). Kept across versions; only missing ones are downloaded.
//  - "page":   everything else (index.html, glue, manifest, icons...). One cache per build,
//    filled completely during install. The old build keeps working until the new one is
//    whole, so an interrupted update can never leave a mixed, broken app.
// Cache-first, so the app starts with no network. A new release changes this file, so the
// browser installs the new build in the background; it is used the next time the app opens.

const APP = '__APP__';
const TAG = '__TAG__';
const BUILD = '__BUILD__';
const STATIC = APP + '-static';
const PAGE = APP + '-page-' + BUILD;
const STATIC_FILES = __STATIC_FILES__;
const PAGE_FILES = __PAGE_FILES__;

const abs = (path) => new URL(path, self.registration.scope).href;

async function download(cache, path, fresh) {
  const request = fresh ? new Request(abs(path), { cache: 'reload' }) : new Request(abs(path));
  const response = await fetch(request);
  if (!response.ok) throw new Error('precache failed: ' + path + ' (' + response.status + ')');
  await cache.put(abs(path), response);
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const stat = await caches.open(STATIC);
    for (const path of STATIC_FILES) {
      if (!(await stat.match(abs(path)))) await download(stat, path, false);
    }
    const page = await caches.open(PAGE);
    for (const path of PAGE_FILES) await download(page, path, true);
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(APP + '-page-') && name !== PAGE) await caches.delete(name);
    }
    const stat = await caches.open(STATIC);
    const keep = new Set(STATIC_FILES.map(abs));
    for (const request of await stat.keys()) {
      if (!keep.has(request.url)) await stat.delete(request);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || request.headers.has('range')) return;
  if (!request.url.startsWith(self.registration.scope)) return;
  event.respondWith((async () => {
    // ignoreSearch: "?webgl", "?cpu" and "?v=<build>" still find the cached file.
    const options = { ignoreSearch: true };
    let hit = await (await caches.open(PAGE)).match(request, options);
    if (!hit) hit = await (await caches.open(STATIC)).match(request, options);
    if (!hit && request.mode === 'navigate') {
      hit = await (await caches.open(PAGE)).match(abs('./index.html'));
    }
    if (hit) return hit;
    try {
      return await fetch(request);
    } catch (error) {
      return new Response('Offline and not cached: ' + request.url, {
        status: 503,
        headers: { 'Content-Type': 'text/plain; charset=utf-8' },
      });
    }
  })());
});
